  -- house 118/2 roll 456 · H.R. 82 · On Passage · 2024-11-12
  --   massie (M001184) stored 'nay' / is_party NULL; the document says 'yea' / with_party
  --   U.S. House roll call 2024-456 — https://clerk.house.gov/evs/2024/roll456.xml
  SELECT id INTO rc FROM vr_rollcalls
   WHERE chamber = 'house' AND congress = 118 AND session = 2
     AND roll_number = 456 LIMIT 1;
  IF rc IS NULL THEN
    RAISE EXCEPTION 'Vote correction: house 118/2 roll 456 is not in vr_rollcalls, so there is no cell to correct.';
  END IF;
  SELECT position INTO cur FROM vr_member_votes WHERE rollcall_id = rc AND politician_id = 'massie';
  IF cur IS NULL THEN
    RAISE EXCEPTION 'Vote correction: house 118/2 roll 456 holds no stored vote for massie. This migration corrects cells that exist and creates none.';
  ELSIF cur = 'nay' THEN
    UPDATE vr_member_votes
       SET position = 'yea', is_party = 'with_party'
     WHERE rollcall_id = rc AND politician_id = 'massie' AND position = 'nay';
    fixed := fixed + 1;
  ELSIF cur = 'yea' THEN
    already := already + 1;
  ELSE
    RAISE EXCEPTION 'Vote correction: house 118/2 roll 456 holds ''%'' for massie, which is neither the value this correction examined (''nay'') nor the value it would write (''yea''). Something changed underneath this migration; refusing to overwrite it.', cur;
