    RAISE EXCEPTION 'Vote correction: house 119/1 roll 151 holds ''%'' for rick_larsen, which is neither the value this correction examined (''yea'') nor the value it would write (''not_voting''). Something changed underneath this migration; refusing to overwrite it.', cur;
  END IF;

  -- house 119/1 roll 201 · H.R. 1919 · On Passage · 2025-07-17
  --   massie (M001184) stored 'yea' / with_party; the document says 'not_voting' / no side
  --   U.S. House roll call 2025-201 — https://clerk.house.gov/evs/2025/roll201.xml
  SELECT id INTO rc FROM vr_rollcalls
   WHERE chamber = 'house' AND congress = 119 AND session = 1
     AND roll_number = 201 LIMIT 1;
  IF rc IS NULL THEN
    RAISE EXCEPTION 'Vote correction: house 119/1 roll 201 is not in vr_rollcalls, so there is no cell to correct.';
  END IF;
  SELECT position INTO cur FROM vr_member_votes WHERE rollcall_id = rc AND politician_id = 'massie';
  IF cur IS NULL THEN
    RAISE EXCEPTION 'Vote correction: house 119/1 roll 201 holds no stored vote for massie. This migration corrects cells that exist and creates none.';
  ELSIF cur = 'yea' THEN
    UPDATE vr_member_votes
       SET position = 'not_voting', is_party = NULL
     WHERE rollcall_id = rc AND politician_id = 'massie' AND position = 'yea';
    fixed := fixed + 1;
  ELSIF cur = 'not_voting' THEN
    already := already + 1;
  ELSE
    RAISE EXCEPTION 'Vote correction: house 119/1 roll 201 holds ''%'' for massie, which is neither the value this correction examined (''yea'') nor the value it would write (''not_voting''). Something changed underneath this migration; refusing to overwrite it.', cur;
  END IF;

  -- senate 119/1 roll 160 · S.J.Res. 37 · On Passage of the Joint Resolution · 2025-04-02
  --   roger_marshall (M001198) stored 'nay' / with_party; the document says 'not_voting' / no side
  --   U.S. Senate roll call 119-1-160 — https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00160.xml
  SELECT id INTO rc FROM vr_rollcalls
   WHERE chamber = 'senate' AND congress = 119 AND session = 1
     AND roll_number = 160 LIMIT 1;
  IF rc IS NULL THEN
    RAISE EXCEPTION 'Vote correction: senate 119/1 roll 160 is not in vr_rollcalls, so there is no cell to correct.';
  END IF;
  SELECT position INTO cur FROM vr_member_votes WHERE rollcall_id = rc AND politician_id = 'roger_marshall';
  IF cur IS NULL THEN
    RAISE EXCEPTION 'Vote correction: senate 119/1 roll 160 holds no stored vote for roger_marshall. This migration corrects cells that exist and creates none.';
  ELSIF cur = 'nay' THEN
    UPDATE vr_member_votes
       SET position = 'not_voting', is_party = NULL
     WHERE rollcall_id = rc AND politician_id = 'roger_marshall' AND position = 'nay';
    fixed := fixed + 1;
  ELSIF cur = 'not_voting' THEN
    already := already + 1;
  ELSE
    RAISE EXCEPTION 'Vote correction: senate 119/1 roll 160 holds ''%'' for roger_marshall, which is neither the value this correction examined (''nay'') nor the value it would write (''not_voting''). Something changed underneath this migration; refusing to overwrite it.', cur;
  END IF;

  RAISE NOTICE 'Vote corrections: % cell(s) corrected, % already correct (of 18 enumerated).', fixed, already;
END $$;
